// Patches the v1 table with the K1 setup literals from t8v1. Does not overwrite v1.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const src = JSON.parse(readFileSync(resolve('work/out/accept-table-t8-v1.json'), 'utf8'));
const BRING = '166805347ccaf26ddad5750dbfd0a2b169855ffa38b4dbcdfa0717ddd42a3059';
const PRE_EDGE = new Set([
  'setup', 'zone-up', 'zone-ok', 'e-enter', 'e-up', 'e-dial', 'e-right', 'e-ok',
  'n-up', 'n-dial', 'n-ok',
]);

src.table = 'accept-table-t8-v2';
src.presets.halfBoot.k1dd1 = [3, 3, 3, 3, 3, 3, 3, 3, 3, 3];
src.presets.halfBoot.k84d1 = [3];
for (const step of src.steps) {
  if (step.id === 'setup' || step.id === 'reopen-base') step.expect.title = BRING;
  if (PRE_EDGE.has(step.id)) step.expect.status = 255;
}
const out = resolve('work/out/accept-table-t8-v2.json');
writeFileSync(out, JSON.stringify(src, null, 2) + '\n');
process.stdout.write(JSON.stringify({
  ok: true, steps: src.steps.length, title: BRING,
  k1dd1: src.presets.halfBoot.k1dd1, k84d1: src.presets.halfBoot.k84d1,
}) + '\n');
